Here's a comprehensive example of a TCP/IP server implemented in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080
#define MAX_BUFFER 1024
#define MAX_CLIENTS 5

// Function to handle client connections
void handle_client(int client_socket) {
    char buffer[MAX_BUFFER];
    int bytes_received;

    // Receive data from client
    while ((bytes_received = recv(client_socket, buffer, sizeof(buffer), 0)) > 0) {
        // Null-terminate the received data
        buffer[bytes_received] = '\0';

        // Print received message
        printf("Received from client: %s\n", buffer);

        // Echo the message back to the client
        send(client_socket, buffer, bytes_received, 0);

        // Clear buffer
        memset(buffer, 0, sizeof(buffer));
    }

    // Close client socket
    close(client_socket);
}

int main() {
    int server_socket, client_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_addr_len = sizeof(client_addr);

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt)) < 0) {
        perror("Socket option setting failed");
        exit(EXIT_FAILURE);
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Binding failed");
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_socket, MAX_CLIENTS) < 0) {
        perror("Listening failed");
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d...\n", PORT);

    // Accept and handle client connections
    while (1) {
        // Accept client connection
        client_socket = accept(server_socket, (struct sockaddr*)&client_addr, &client_addr_len);
        if (client_socket < 0) {
            perror("Accept failed");
            continue;
        }

        // Print client connection details
        char client_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &(client_addr.sin_addr), client_ip, INET_ADDRSTRLEN);
        printf("Connected with client: %s:%d\n", client_ip, ntohs(client_addr.sin_port));

        // Create a child process to handle client
        pid_t pid = fork();

        if (pid < 0) {
            perror("Fork failed");
            close(client_socket);
            continue;
        }
        else if (pid == 0) {
            // Child process
            close(server_socket);  // Close parent socket in child
            handle_client(client_socket);
            exit(EXIT_SUCCESS);
        }
        else {
            // Parent process
            close(client_socket);  // Close client socket in parent
        }
    }

    // Close server socket
    close(server_socket);

    return 0;
}
```

This TCP/IP server implementation includes several key features:

1. Socket Creation:
- Creates a TCP socket using `socket()` function
- Configures socket options with `setsockopt()`
- Binds socket to a specific port

2. Connection Handling:
- Listens for incoming client connections
- Accepts client connections using `accept()`
- Creates a child process for each client connection

3. Client Communication:
- Receives data from clients using `recv()`
- Sends data back to clients using `send()`
- Handles multiple simultaneous client connections

4. Error Handling:
- Includes error checking and handling for socket operations
- Provides informative error messages

5. Multiprocessing:
- Uses `fork()` to create separate processes for each client
- Allows concurrent handling of multiple client connections

Key Points:
- Server listens on port 8080 (configurable)
- Supports up to 5 simultaneous client connections
- Echoes received messages back to clients
- Prints client connection details

Compilation and Execution:
```bash
# Compile the server
gcc -o tcp_server tcp_server.c

# Run the server
./tcp_server
```

You can test this server using tools like `netcat` or by creating a corresponding TCP client.

Note: This is a basic implementation. For production environments, consider:
- Using threads instead of processes
- Implementing more robust error handling
- Adding timeout mechanisms
- Implementing secure communication protocols

